#!/bin/bash
# Rebuild the checked-in resource from immutable, verified upstream blobs.
set -euo pipefail

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
OUTPUT="$ROOT/Sources/Textual/Internal/Highlighter/Prism/prism-bundle.js"
UPSTREAM="76dde18a575831c91491895193f56081ac08b0c5"
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

cat > "$TMP/bundle.js" <<'HEADER'
// Prism.js v1.30.0 (upstream 76dde18a575831c91491895193f56081ac08b0c5)
// Auto-generated by Scripts/bundle-prism.sh - DO NOT EDIT

HEADER
while read -r expected path; do
  curl --proto '=https' --fail --silent --show-error \
    "https://raw.githubusercontent.com/PrismJS/prism/$UPSTREAM/$path" > "$TMP/input"
  if [[ $(git hash-object "$TMP/input") != "$expected" ]]; then
    printf 'Unexpected upstream bytes: %s\n' "$path" >&2
    exit 1
  fi
  # Normalize only trailing newlines to match the committed bundle.
  if [[ "$path" == LICENSE ]]; then printf '/*\n' >> "$TMP/bundle.js"; fi
  printf '%s\n' "$(cat "$TMP/input")" >> "$TMP/bundle.js"
  if [[ "$path" == LICENSE ]]; then printf '*/\n\n' >> "$TMP/bundle.js"; fi
done <<'FILES'
